const uint8_t *font_cn16_get_bitmap(uint16_t unicode)
{
    int lo = 0, hi = FONT_CN16_COUNT - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        uint16_t c = g_font_cn16_codes[mid];
        if (c == unicode) return g_font_cn16_bitmaps[mid];
        if (c < unicode) lo = mid + 1;
        else hi = mid - 1;
    }
    return NULL;
}
